arguments.command:
curl -s -X POST https://slack.com/api/conversations.list -d 'token=<TOKEN>' -d 'types=public_channel,private_channel' | python3 -c "
import json,sys
d=json.load(sys.stdin)
if not d.get('ok'):
    print('ERR', d)
else:
    for c in d['channels']:
        print(c['id'], c.get('name'), c.get('is_private'))
"

